const $=id=>document.getElementById(id);let missing=false;const series={normal:[80,75,70,65],low:[43,37,31,25],stale:[70,65,60,55],missing:[]};
function update(){try{$('error').textContent='';const l=Water.number($('level').value,0,100),a=Water.number($('age').value,0,1440);let r=Water.reading(l,a);if(missing)r={status:'unknown',text:'Sin lectura: nivel actual desconocido.'};const digital=document.querySelector('[name=mode]:checked').value==='digital';$('rangehelp').textContent=r.status==='unknown'?'No hay un intervalo actual disponible.':`Podría estar entre ${Math.max(0,l-5)}% y ${Math.min(100,l+5)}%. Margen ilustrativo, no calibrado.`;$('result').textContent=r.status==='unknown'?'Nivel desconocido':`${l}% ± 5 puntos`;$('water').style.height=r.status==='unknown'?'0%':l+'%';$('tanklabel').textContent=r.status==='unknown'?'?':l+'%';$('status').textContent=r.text+(r.status==='low'||r.status==='uncertain'?' En un piloto, usa solo el indicador local instalado por personal calificado. No subas, abras ni te asomes al tanque.':'');$('ml').textContent='Modo manual: las alertas digitales están desactivadas.';if(digital){const ys=series[$('scenario').value];const f=r.status==='unknown'?null:Water.forecast([0,1,2,3],ys,l,a);$('ml').textContent=r.status==='unknown'?'Alerta digital: no hay una lectura actual confiable.':r.status==='uncertain'?'Alerta digital simulada: el margen puede incluir un nivel bajo. Confirma con una referencia segura.':l<=25?'Alerta digital simulada: nivel bajo. Confirma con una referencia segura.':f?`ML con datos sintéticos: ~${f.hours.toFixed(1)} h hasta 25% si continúa la tendencia. No es un aviso garantizado.`:'ML: sin estimación útil para esta tendencia.';}}catch(e){$('error').textContent=e.message;$('result').textContent='Nivel desconocido';$('status').textContent='Corrige la lectura antes de usarla.';$('ml').textContent='';}}
['level','age'].forEach(id=>$(id).addEventListener('input',update));
$('readingform').onsubmit=e=>{e.preventDefault();update()};document.querySelectorAll('[name=mode]').forEach(x=>x.onchange=update);$('scenario').onchange=()=>{const s=$('scenario').value;missing=s==='missing';$('level').value=s==='low'?25:s==='stale'?55:65;$('age').value=s==='stale'?120:5;update()};$('action').onchange=()=>{$('next').textContent={schedule:'Consulta una fuente local de confianza para saber si existe un horario actualizado. Este prototipo no verifica el suministro.',support:'Elige tú a una persona de confianza. No enviamos mensajes ni compartimos lecturas.',none:'No tener una opción es una limitación del servicio, no una falla tuya. Una alerta no resuelve el acceso. En un piloto futuro se podría registrar con tu permiso. Esta demostración no guarda tu selección.','':'Elige una opción. No hacemos solicitudes en tu nombre.'}[$('action').value]};
function calculate(){try{$('costerror').textContent='';const ids=['equipment','installation','support','training','digital','overhead','fee'];const values=ids.map(id=>$(id).value);const c=Water.costs(values),manual=c.total-Number($('digital').value),fmt=n=>n.toLocaleString('es-MX',{style:'currency',currency:'MXN'});$('costresult').replaceChildren();[['Manual / año 1',fmt(manual)],['Con digital / año 1',fmt(c.total)],['Contribución',fmt(c.contribution)],['Margen',c.margin===null?'Sin cuota':c.margin.toFixed(1)+'%']].forEach(([label,value])=>{const d=document.createElement('div');d.textContent=label;const s=document.createElement('strong');s.textContent=value;d.append(s);$('costresult').append(d)})}catch(e){$('costresult').textContent='Costo no calculado.';$('costerror').textContent=e.message;}}
$('costform').onsubmit=e=>{e.preventDefault();calculate()};$('clear').onclick=()=>location.reload();update();calculate();$('action').dispatchEvent(new Event('change'));
